const listSubscriptionsAdmin = `-- name: ListSubscriptionsAdmin :many
SELECT latest.id, latest.uuid, latest.organization_id, latest.plan_id, latest.period, latest.status, latest.starts_at, latest.ends_at, latest.grace_ends_at, latest.price_paid, latest.credit_balance, latest.custom_features, latest.source, latest.note, latest.created_by, latest.created_at, latest.updated_at, p.code AS plan_code, p.name AS plan_name, p.uuid AS plan_uuid,
    org.uuid AS organization_uuid, org.slug AS organization_slug, org.name AS organization_name
FROM (
    SELECT DISTINCT ON (organization_id) id, uuid, organization_id, plan_id, period, status, starts_at, ends_at, grace_ends_at, price_paid, credit_balance, custom_features, source, note, created_by, created_at, updated_at
    FROM billing_subscriptions
    ORDER BY organization_id, created_at DESC
) latest
JOIN billing_plans p ON p.id = latest.plan_id
JOIN organizations org ON org.id = latest.organization_id
WHERE ($1::text = '' OR latest.status = $1::text)
    AND ($2::uuid IS NULL OR p.uuid = $2::uuid)
    AND (
        $3::timestamptz IS NULL
        OR (
            latest.status IN ('trial', 'active')
            AND latest.ends_at > NOW()
            AND latest.ends_at <= $3::timestamptz
        )
    )
    AND (
        $4::text = ''
        OR org.name ILIKE '%' || $4::text || '%'
        OR org.slug ILIKE '%' || $4::text || '%'
    )
ORDER BY latest.created_at DESC, latest.id DESC
LIMIT $6 OFFSET $5
`

